const rawSql = ($input.first().json.text || '').trim();

if (!rawSql) {
  return [{
    json: {
      isValid: false,
      reason: 'Empty SQL',
      sql: rawSql,
    }
  }];
}

const sql = rawSql
  .replace(/```sql/gi, '')
  .replace(/```/g, '')
  .trim();

const forbiddenKeywords = [
  'INSERT', 'UPDATE', 'DELETE', 'DROP', 'ALTER', 'TRUNCATE',
  'CREATE', 'GRANT', 'REVOKE', 'MERGE', 'CALL', 'DO', 'COPY',
  'EXECUTE', 'BEGIN', 'COMMIT', 'ROLLBACK'
];

const allowStart = /^(SELECT|WITH)\b/i;
const multiStatement = /;[\s\r\n]*\S+/;
const forbiddenPattern = new RegExp(`\\b(${forbiddenKeywords.join('|')})\\b`, 'i');

const allowedTables = [
  'public.products',
  'public.stock',
  'public.warehouses',
  'public.product_categories',
  'public.attachments',
  'public.product_attachments',
  'public.promotions',
  'public.promotion_products',
  'public.promotion_groups',
  'public.promotion_attachments',
  'public.product_suppliers',
  'public.brands',
  'public.stock_inquiries',
  'public.purchase_requests',
  'public.purchase_request_lines',
  'public.forms',
  'public.order_statuses',
  'public.orders',
  'public.order_lines',
  'public.inbound_shipments',
  'public.inbound_shipment_lines',
  'public.spo_allocations',
  'public.picking_headers',
  'public.picking_lines',
  'products',
  'stock',
  'warehouses',
  'product_categories',
  'attachments',
  'product_attachments',
  'promotions',
  'promotion_products',
  'promotion_groups',
  'promotion_attachments',
  'product_suppliers',
  'brands',
  'stock_inquiries',
  'purchase_requests',
  'purchase_request_lines',
  'forms',
  'order_statuses',
  'orders',
  'order_lines',
  'inbound_shipments',
  'inbound_shipment_lines',
  'spo_allocations',
  'picking_headers',
  'picking_lines'
];

const deniedSchemas = /\b(information_schema|pg_catalog|pg_shadow|pg_user|pg_roles)\b/i;

const problems = [];

if (!allowStart.test(sql)) {
  problems.push('Only SELECT or WITH queries are allowed');
}

if (forbiddenPattern.test(sql)) {
  problems.push('Forbidden SQL keyword detected');
}

if (multiStatement.test(sql.replace(/;\s*$/, ''))) {
  problems.push('Multiple SQL statements are not allowed');
}

if (deniedSchemas.test(sql)) {
  problems.push('System schemas are not allowed');
}

const lowerSql = sql.toLowerCase();

const tableRegex = /\b(from|join)\s+([a-zA-Z0-9_."]+)/gi;
let match;
const referencedTables = [];

while ((match = tableRegex.exec(sql)) !== null) {
  const tableName = match[2].replace(/"/g, '');
  referencedTables.push(tableName);
}

const invalidTables = referencedTables.filter(t => {
  const normalized = t.toLowerCase();
  return !allowedTables.map(a => a.toLowerCase()).includes(normalized);
});

if (invalidTables.length > 0) {
  problems.push(`Disallowed table(s): ${[...new Set(invalidTables)].join(', ')}`);
}

const hasLimit = /\blimit\s+\d+\b/i.test(sql);
let safeSql = sql.replace(/;+\s*$/, '');

if (!hasLimit) {
  safeSql += '\nLIMIT 100';
}

const hasOrderBy = /\border\s+by\b/i.test(sql);
const isAggregateOnly =
  /\b(count|sum|avg|min|max)\s*\(/i.test(sql) &&
  !/\b(product_code|product_name|promo_code|warehouse_code|original_filename)\b/i.test(sql);

return [{
  json: {
    isValid: problems.length === 0,
    reason: problems.join('; '),
    sql: rawSql,
    normalizedSql: safeSql,
    referencedTables: [...new Set(referencedTables)],
    hasLimit,
    hasOrderBy,
    isAggregateOnly,
  }
}];

if ($input.first().json.isValid == false) {
  return {
    "output": "Invalid query"
  }
} else if (Object.keys($input.first().json).length > 0) {
  return $input.all()
} else {
  return {
    "output": "No result"
  }
}
